import { useEffect, useState } from "react";
import { Activity, BrainCircuit, Check, CircleAlert, CircleDollarSign, Database, ListChecks, Loader2, Mail, Menu, Radio, RefreshCw, Search, Send, ShieldCheck, Users, X } from "lucide-react";
import { createFileRoute, Link } from "@tanstack/react-router";
import { adminApi, type AdminAiProviderConfig, type AdminAllocationRequest, type AdminControlTowerSnapshot, type AdminCustomerAccount, type AdminOperationsMetrics, type AdminTelemetrySummary, type ManagedSecretMetadata, type StaffManagementData, type StaffNotificationRecipient, type TargetComplaint, type TargetComplaintStatus, type WorkerHealth } from "@/lib/api-client";
import { StaffManagementPanel } from "@/components/staff-management-panel";
import { useAuth } from "@/lib/auth-context";
import { AdminAiModelsTab } from "@/components/admin-ai-models-tab";
import { AdminSecretsTab } from "@/components/admin-secrets-tab";

export const Route = createFileRoute("/admin")({
  head: () => ({ meta: [{ title: "Admin Console · Matrix QA" }, { name: "robots", content: "noindex" }] }),
  component: AdminPage,
});

type AdminTab = "control_tower" | "queue" | "notifications" | "telemetry" | "ai_models" | "secrets" | "staff" | "customers" | "complaints";

function AdminPage() {
  const { user, isLoading } = useAuth();
  const [tab, setTab] = useState<AdminTab>("control_tower");
  const [requests, setRequests] = useState<AdminAllocationRequest[]>([]);
  const [recipients, setRecipients] = useState<StaffNotificationRecipient[]>([]);
  const [telemetry, setTelemetry] = useState<AdminTelemetrySummary | null>(null);
  const [controlTower, setControlTower] = useState<AdminControlTowerSnapshot | null>(null);
  const [metrics, setMetrics] = useState<AdminOperationsMetrics | null>(null);
  const [aiProviders, setAiProviders] = useState<AdminAiProviderConfig[]>([]);
  const [secrets, setSecrets] = useState<ManagedSecretMetadata[]>([]);
  const [health, setHealth] = useState<WorkerHealth | null>(null);
  const [staffData, setStaffData] = useState<StaffManagementData | null>(null);
  const [customers, setCustomers] = useState<AdminCustomerAccount[]>([]);
  const [complaints, setComplaints] = useState<TargetComplaint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [recipientEmail, setRecipientEmail] = useState("");
  const [recipientLabel, setRecipientLabel] = useState("");
  const [broadcastTitle, setBroadcastTitle] = useState("");
  const [broadcastMessage, setBroadcastMessage] = useState("");
  const [broadcastAudience, setBroadcastAudience] = useState<"ALL_USERS" | "STAFF">("ALL_USERS");
  const [busyId, setBusyId] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError("");
    try {
      const canManageStaff = user?.staffRole === "OWNER" || user?.staffRole === "OPERATIONS_ADMIN";
      const [requestData, recipientData, telemetryData, aiProviderData, healthData, managedSecretData, staffManagementData, controlTowerData, metricsData, customerData, complaintData] = await Promise.all([
        adminApi.listAllocationRequests("PENDING"),
        adminApi.listRecipients(),
        adminApi.telemetry(),
        adminApi.listAiProviderConfigs(),
        adminApi.workerHealth(),
        canManageStaff ? adminApi.listManagedSecrets() : Promise.resolve([]),
        canManageStaff ? adminApi.listStaff() : Promise.resolve(null),
        adminApi.controlTower(),
        adminApi.metrics(7),
        adminApi.listCustomerAccounts(),
        adminApi.listTargetComplaints(),
      ]);
      setRequests(requestData);
      setRecipients(recipientData);
      setTelemetry(telemetryData);
      setAiProviders(aiProviderData);
      setHealth(healthData);
      setSecrets(managedSecretData);
      setStaffData(staffManagementData);
      setControlTower(controlTowerData);
      setMetrics(metricsData);
      setCustomers(customerData);
      setComplaints(complaintData);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Unable to load staff console data.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { if (user?.isStaff) void load(); }, [user?.isStaff]);

  const review = async (request: AdminAllocationRequest, status: "APPROVED" | "DECLINED") => {
    const note = window.prompt(status === "APPROVED" ? "Optional approval note" : "Reason for declining this request", "") ?? "";
    if (status === "DECLINED" && !note.trim()) return;
    setBusyId(request.id); setError(""); setMessage("");
    try {
      await adminApi.reviewAllocationRequest(request.id, { status, staffNote: note.trim() || undefined });
      setRequests((current) => current.filter((item) => item.id !== request.id));
      setMessage(`Request ${status === "APPROVED" ? "approved" : "declined"}. The requester was notified.`);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Unable to review allocation request.");
    } finally { setBusyId(null); }
  };

  const saveRecipient = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!recipientEmail.trim()) return;
    setBusyId("recipient"); setError(""); setMessage("");
    try {
      const saved = await adminApi.saveRecipient({ email: recipientEmail.trim(), label: recipientLabel.trim() || undefined });
      setRecipients((current) => [...current.filter((item) => item.id !== saved.id), saved].sort((a, b) => a.email.localeCompare(b.email)));
      setRecipientEmail(""); setRecipientLabel(""); setMessage("Notification recipient saved.");
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to save recipient."); }
    finally { setBusyId(null); }
  };

  const disableRecipient = async (recipient: StaffNotificationRecipient) => {
    setBusyId(recipient.id); setError("");
    try {
      const disabled = await adminApi.disableRecipient(recipient.id);
      setRecipients((current) => current.map((item) => item.id === disabled.id ? disabled : item));
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to disable recipient."); }
    finally { setBusyId(null); }
  };

  const saveAiProvider = async (data: Partial<AdminAiProviderConfig> & Pick<AdminAiProviderConfig, "provider" | "model" | "useCase" | "secretRef">) => {
    setBusyId(`ai-provider-${data.useCase}`); setError(""); setMessage("");
    try {
      const saved = await adminApi.saveAiProviderConfig(data);
      setAiProviders((current) => [...current.filter((item) => item.id !== saved.id), saved].sort((a, b) => a.useCase.localeCompare(b.useCase) || a.priority - b.priority));
      setMessage(`${saved.provider} / ${saved.model} saved for ${saved.useCase}. New scans use it after activation.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to save AI provider configuration."); }
    finally { setBusyId(null); }
  };

  const removeAiProvider = async (config: AdminAiProviderConfig) => {
    setBusyId(`ai-remove-${config.id}`); setError(""); setMessage("");
    try {
      await adminApi.deleteAiProviderConfig(config.id);
      setAiProviders((current) => current.filter((item) => item.id !== config.id));
      setMessage(`${config.provider} / ${config.model} removed from ${config.useCase}.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to remove AI provider configuration."); }
    finally { setBusyId(null); }
  };

  const healthCheckAiProvider = async (config: AdminAiProviderConfig) => {
    setBusyId(`ai-health-${config.id}`); setError(""); setMessage("");
    try {
      const checked = await adminApi.healthCheckAiProviderConfig(config.id);
      setAiProviders((current) => current.map((item) => item.id === checked.id ? checked : item));
      setMessage(`${checked.provider} / ${checked.model}: ${checked.lastHealthStatus || "checked"}.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to check AI provider configuration."); }
    finally { setBusyId(null); }
  };

  const saveManagedSecret = (secret: ManagedSecretMetadata) => {
    setSecrets((current) => [...current.filter((item) => item.name !== secret.name), secret].sort((a, b) => a.name.localeCompare(b.name)));
  };

  const deleteManagedSecret = (name: string) => setSecrets((current) => current.filter((item) => item.name !== name));

  const sendBroadcast = async (event: React.FormEvent) => {
    event.preventDefault();
    setBusyId("broadcast"); setError(""); setMessage("");
    try {
      const result = await adminApi.broadcast({ title: broadcastTitle.trim(), message: broadcastMessage.trim(), audience: broadcastAudience });
      setBroadcastTitle(""); setBroadcastMessage("");
      setMessage(`Broadcast delivered to ${result.deliveredCount} ${result.audience === "STAFF" ? "staff members" : "users"}.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to send broadcast."); }
    finally { setBusyId(null); }
  };

  const changeCustomerStatus = async (customer: AdminCustomerAccount, status: "ACTIVE" | "SUSPENDED" | "DISABLED") => {
    const reason = window.prompt(status === "ACTIVE" ? "Optional reactivation note" : `Reason for ${status.toLowerCase()} this customer account`, "") ?? "";
    if (status !== "ACTIVE" && reason.trim().length < 3) return;
    setBusyId(`customer-${customer.id}`); setError(""); setMessage("");
    try {
      const updated = await adminApi.changeCustomerAccountStatus(customer.id, { status, reason: reason.trim() || undefined });
      setCustomers((current) => current.map((item) => item.id === updated.id ? { ...item, accountStatus: updated.accountStatus } : item));
      setMessage(`${customer.email} is now ${status.toLowerCase()}; active sessions were revoked.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to change the customer account status."); }
    finally { setBusyId(null); }
  };

  const reviewComplaint = async (complaint: TargetComplaint, status: TargetComplaintStatus) => {
    const staffNote = window.prompt(`Optional note for ${status.toLowerCase().replaceAll("_", " ")}`, complaint.staffNote ?? "") ?? "";
    setBusyId(`complaint-${complaint.id}`); setError(""); setMessage("");
    try {
      const updated = await adminApi.reviewTargetComplaint(complaint.id, { status, staffNote: staffNote.trim() || undefined });
      setComplaints((current) => current.map((item) => item.id === updated.id ? { ...item, ...updated } : item));
      setMessage(`Target complaint marked ${status.toLowerCase().replaceAll("_", " ")}; the reporter was notified.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to review the target complaint."); }
    finally { setBusyId(null); }
  };

  if (isLoading) return <div className="flex min-h-screen items-center justify-center text-sm text-muted-foreground"><Loader2 className="mr-2 h-4 w-4 animate-spin" /> Checking staff access…</div>;
  if (!user) return <AdminAccessGate title="Staff sign-in required" message="The Matrix QA admin console is restricted to staff accounts." action={<Link to="/auth" search={{ mode: "signin", returnTo: "/admin" }} className="inline-flex items-center rounded-md bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground">Sign in as staff</Link>} />;
  if (!user.isStaff) return <AdminAccessGate title="Staff access required" message="Your account is signed in, but it is not enabled for Matrix QA staff operations." action={<Link to="/app" className="inline-flex items-center rounded-md border border-border px-3 py-2 text-xs font-semibold text-foreground">Return to console</Link>} />;

  return <AdminShell activeTab={tab} onTabChange={(nextTab) => { setTab(nextTab); }} canManageStaff={user.staffRole === "OWNER" || user.staffRole === "OPERATIONS_ADMIN"}><div className="mx-auto max-w-7xl px-4 py-6 md:px-8 md:py-8">
    <div className="flex flex-wrap items-end justify-between gap-3"><div><div className="flex items-center gap-2 text-xs font-mono uppercase tracking-widest text-primary"><ShieldCheck className="h-4 w-4" /> Matrix QA staff</div><h1 className="mt-2 font-display text-2xl font-semibold">Admin console</h1><p className="mt-1 text-sm text-muted-foreground">Private-alpha operations, allocation decisions, notifications, and cost telemetry.</p></div><button type="button" onClick={() => void load()} className="inline-flex items-center gap-1.5 rounded-md border border-border px-3 py-2 text-xs font-medium hover:bg-accent"><RefreshCw className="h-3.5 w-3.5" /> Refresh</button></div>
    {error && <div className="mt-5 rounded-md border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</div>}{message && <div className="mt-5 rounded-md border border-primary/30 bg-primary/10 p-3 text-sm text-primary">{message}</div>}
    {loading ? <div className="flex items-center gap-2 py-20 text-sm text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading staff data…</div> : tab === "control_tower" ? <ControlTowerTab snapshot={controlTower} metrics={metrics} providers={aiProviders} onOpenAiModels={() => setTab("ai_models")} /> :
 tab === "queue" ? <QueueTab requests={requests} busyId={busyId} onReview={review} /> : tab === "notifications" ? <NotificationsTab recipients={recipients} recipientEmail={recipientEmail} recipientLabel={recipientLabel} setRecipientEmail={setRecipientEmail} setRecipientLabel={setRecipientLabel} busyId={busyId} onSave={saveRecipient} onDisable={disableRecipient} broadcastTitle={broadcastTitle} broadcastMessage={broadcastMessage} broadcastAudience={broadcastAudience} setBroadcastTitle={setBroadcastTitle} setBroadcastMessage={setBroadcastMessage} setBroadcastAudience={setBroadcastAudience} onBroadcast={sendBroadcast} /> : tab === "customers" ? <CustomersTab customers={customers} busyId={busyId} onStatusChange={changeCustomerStatus} /> : tab === "complaints" ? <ComplaintsTab complaints={complaints} busyId={busyId} onReview={reviewComplaint} /> : tab === "telemetry" ? <TelemetryTab telemetry={telemetry} health={health} /> : tab === "ai_models" ? <AdminAiModelsTab configs={aiProviders} busyId={busyId} managedSecretNames={secrets.map((secret) => secret.name)} onSave={saveAiProvider} onHealthCheck={healthCheckAiProvider} onRemove={removeAiProvider} /> : tab === "secrets" && (user.staffRole === "OWNER" || user.staffRole === "OPERATIONS_ADMIN") ? <AdminSecretsTab secrets={secrets} role={user.staffRole} busyId={busyId} onSaved={saveManagedSecret} onDeleted={deleteManagedSecret} setMessage={setMessage} setError={setError} /> : staffData ? <StaffManagementPanel data={staffData} role={user.staffRole} onChanged={load} setMessage={setMessage} setError={setError} /> : <div className="mt-6 surface-card p-6 text-sm text-muted-foreground">Staff management is available to owners and operations administrators.</div>}
  </div></AdminShell>;
}

function AdminShell({ activeTab, onTabChange, canManageStaff, children }: { activeTab: AdminTab; onTabChange: (tab: AdminTab) => void; canManageStaff: boolean; children: React.ReactNode }) {
  const { user } = useAuth();
  const [mobileOpen, setMobileOpen] = useState(false);
  const groups: Array<{ label: string; items: Array<{ key: AdminTab; label: string; icon: typeof Activity }> }> = [
    { label: "Overview", items: [{ key: "control_tower", label: "Control tower", icon: Activity }] },
    { label: "Operations", items: [{ key: "queue", label: "Queue & capacity", icon: ListChecks }, { key: "telemetry", label: "Telemetry", icon: Radio }, { key: "notifications", label: "Notifications", icon: Mail }] },
    { label: "Security", items: [{ key: "customers", label: "Customer accounts", icon: Users }, { key: "complaints", label: "Target complaints", icon: CircleAlert }] },
    { label: "Configuration", items: [{ key: "ai_models", label: "AI providers", icon: BrainCircuit }, ...(canManageStaff ? [{ key: "secrets" as const, label: "Secrets", icon: Database }, { key: "staff" as const, label: "Staff management", icon: Users }] : [])] },
  ];
  const sidebar = <div className="flex h-full flex-col bg-[#122033] text-slate-300"><div className="flex h-16 items-center gap-3 border-b border-white/10 px-5"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#2f6fed] font-display text-sm font-bold text-white">M</div><div><div className="font-display text-sm font-semibold tracking-wide text-white">Matrix QA</div><div className="text-[10px] uppercase tracking-[0.18em] text-slate-400">Control tower</div></div></div><div className="border-b border-white/10 px-5 py-4"><div className="text-[10px] uppercase tracking-[0.18em] text-slate-500">Operations workspace</div><div className="mt-1 truncate text-sm font-medium text-slate-100">Private alpha</div></div><nav aria-label="Admin navigation" className="flex-1 overflow-y-auto px-3 py-4">{groups.map((group) => <div key={group.label} className="mb-5"><div className="px-3 pb-2 text-[10px] font-semibold uppercase tracking-[0.18em] text-slate-500">{group.label}</div><div className="space-y-1">{group.items.map((item) => { const Icon = item.icon; const active = activeTab === item.key; return <button key={item.key} type="button" onClick={() => { onTabChange(item.key); setMobileOpen(false); }} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm ${active ? "bg-[#2f6fed] font-semibold text-white" : "text-slate-300 hover:bg-white/10 hover:text-white"}`}><Icon className="h-4 w-4" />{item.label}</button>; })}</div></div>)}</nav><div className="border-t border-white/10 p-4"><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-600 text-xs font-semibold text-white">{(user?.fullName || user?.email || "MQ").slice(0, 2).toUpperCase()}</div><div className="min-w-0"><div className="truncate text-xs font-medium text-white">{user?.fullName || "Staff operator"}</div><div className="truncate text-[10px] text-slate-400">{user?.staffRole || "Staff"}</div></div></div></div></div>;
  return <div className="min-h-screen bg-[#f4f7fb] text-slate-900"><aside className="fixed inset-y-0 left-0 z-30 hidden w-64 lg:flex">{sidebar}</aside>{mobileOpen && <div className="fixed inset-0 z-40 lg:hidden"><button type="button" aria-label="Close admin navigation" className="absolute inset-0 bg-slate-950/60" onClick={() => setMobileOpen(false)} /> <aside className="relative h-full w-72 shadow-2xl">{sidebar}</aside></div>}<div className="min-h-screen lg:pl-64"><header className="sticky top-0 z-20 flex min-h-16 items-center gap-3 border-b border-slate-200 bg-white/95 px-4 backdrop-blur md:px-8"><button type="button" className="rounded-md p-2 text-slate-500 hover:bg-slate-100 lg:hidden" aria-label="Open admin navigation" onClick={() => setMobileOpen(true)}><Menu className="h-5 w-5" /></button><div className="relative hidden max-w-md flex-1 md:block"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input aria-label="Search admin console" placeholder="Search runs, organizations, findings…" className="w-full rounded-lg border border-slate-200 bg-slate-50 py-2 pl-9 pr-3 text-sm outline-none focus:border-[#2f6fed]" /></div><div className="ml-auto flex items-center gap-4 text-xs text-slate-500"><span className="hidden items-center gap-2 sm:flex"><span className="h-2 w-2 rounded-full bg-emerald-500" />Systems operational</span><span className="hidden h-5 w-px bg-slate-200 sm:block" /> <span className="font-medium text-slate-700">Staff console</span></div></header><main className="min-h-[calc(100vh-4rem)]">{children}</main></div></div>;
}

function AdminAccessGate({ title, message, action }: { title: string; message: string; action: React.ReactNode }) { return <div className="flex min-h-screen items-center justify-center bg-background px-6 text-center"><div className="max-w-md"><ShieldCheck className="mx-auto h-8 w-8 text-primary" /><h1 className="mt-4 font-display text-xl font-semibold">{title}</h1><p className="mt-2 text-sm leading-6 text-muted-foreground">{message}</p><div className="mt-5">{action}</div></div></div>; }


function CustomersTab({ customers, busyId, onStatusChange }: { customers: AdminCustomerAccount[]; busyId: string | null; onStatusChange: (customer: AdminCustomerAccount, status: "ACTIVE" | "SUSPENDED" | "DISABLED") => void }) {
  const active = customers.filter((customer) => customer.accountStatus === "ACTIVE").length;
  const suspended = customers.filter((customer) => customer.accountStatus === "SUSPENDED").length;
  const disabled = customers.filter((customer) => customer.accountStatus === "DISABLED").length;
  return <div className="space-y-5"><div><div className="font-mono text-[10px] uppercase tracking-[0.18em] text-primary">Security / lifecycle</div><h2 className="mt-2 font-display text-xl font-semibold">Customer accounts</h2><p className="mt-1 text-sm text-muted-foreground">Review account access, revoke active sessions, and keep the private alpha under control.</p></div><div className="grid gap-3 sm:grid-cols-3"><MetricCard label="Active" value={active} tone="success" /><MetricCard label="Suspended" value={suspended} tone="warning" /><MetricCard label="Disabled" value={disabled} tone="danger" /></div><section className="surface-card overflow-hidden"><header className="flex items-center justify-between border-b border-border px-5 py-4"><div><h3 className="font-display text-base font-semibold">Customer directory</h3><p className="mt-1 text-xs text-muted-foreground">Account state changes revoke sessions immediately and create audit records.</p></div><span className="font-mono text-xs text-muted-foreground">{customers.length} accounts</span></header><div className="max-h-[34rem] divide-y divide-border overflow-y-auto">{customers.length === 0 ? <p className="p-5 text-sm text-muted-foreground">No customer accounts found.</p> : customers.map((customer) => <div key={customer.id} className="flex flex-col gap-3 px-5 py-4 lg:flex-row lg:items-center lg:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="truncate text-sm font-semibold">{customer.fullName || "Unnamed customer"}</span><span className={`rounded-full border px-2 py-0.5 font-mono text-[10px] uppercase tracking-wider ${customer.accountStatus === "ACTIVE" ? "border-success/30 bg-success/10 text-success" : customer.accountStatus === "SUSPENDED" ? "border-warning/30 bg-warning/10 text-warning" : "border-destructive/30 bg-destructive/10 text-destructive"}`}>{customer.accountStatus}</span></div><div className="mt-1 truncate text-xs text-muted-foreground">{customer.email} · joined {new Date(customer.createdAt).toLocaleDateString()} · {customer.emailVerified ? "verified" : "unverified"}</div><div className="mt-2 text-[11px] text-muted-foreground">{customer.organizationCount} organizations · {customer.runCount} triggered runs</div></div><div className="flex shrink-0 flex-wrap gap-2"><button type="button" onClick={() => onStatusChange(customer, "ACTIVE")} disabled={busyId === `customer-${customer.id}` || customer.accountStatus === "ACTIVE"} className="rounded-md border border-success/30 px-2.5 py-1.5 text-[11px] font-medium text-success hover:bg-success/10 disabled:opacity-40">Reactivate</button><button type="button" onClick={() => onStatusChange(customer, "SUSPENDED")} disabled={busyId === `customer-${customer.id}` || customer.accountStatus === "SUSPENDED"} className="rounded-md border border-warning/30 px-2.5 py-1.5 text-[11px] font-medium text-warning hover:bg-warning/10 disabled:opacity-40">Suspend</button><button type="button" onClick={() => onStatusChange(customer, "DISABLED")} disabled={busyId === `customer-${customer.id}` || customer.accountStatus === "DISABLED"} className="rounded-md border border-destructive/30 px-2.5 py-1.5 text-[11px] font-medium text-destructive hover:bg-destructive/10 disabled:opacity-40">Disable</button></div></div>)}</div></section></div>;
}

function ComplaintsTab({ complaints, busyId, onReview }: { complaints: TargetComplaint[]; busyId: string | null; onReview: (complaint: TargetComplaint, status: TargetComplaintStatus) => void }) {
  const open = complaints.filter((complaint) => complaint.status === "OPEN" || complaint.status === "UNDER_REVIEW").length;
  return <div className="space-y-5"><div><div className="font-mono text-[10px] uppercase tracking-[0.18em] text-primary">Security / target integrity</div><h2 className="mt-2 font-display text-xl font-semibold">Target complaints</h2><p className="mt-1 text-sm text-muted-foreground">Review customer reports about unsafe, incorrect, or unexpectedly reachable targets. Every decision is notified and audited.</p></div><div className="grid gap-3 sm:grid-cols-3"><MetricCard label="Open review" value={open} tone="warning" /><MetricCard label="Resolved" value={complaints.filter((complaint) => complaint.status === "RESOLVED").length} tone="success" /><MetricCard label="Dismissed" value={complaints.filter((complaint) => complaint.status === "DISMISSED").length} tone="neutral" /></div><section className="surface-card overflow-hidden"><header className="flex items-center justify-between border-b border-border px-5 py-4"><div><h3 className="font-display text-base font-semibold">Complaint queue</h3><p className="mt-1 text-xs text-muted-foreground">Customer target reports are retained for operational review.</p></div><span className="font-mono text-xs text-muted-foreground">{complaints.length} reports</span></header><div className="max-h-[34rem] divide-y divide-border overflow-y-auto">{complaints.length === 0 ? <p className="p-5 text-sm text-muted-foreground">No target complaints have been submitted.</p> : complaints.map((complaint) => <div key={complaint.id} className="space-y-3 px-5 py-4"><div className="flex flex-col gap-2 lg:flex-row lg:items-start lg:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{complaint.status.replaceAll("_", " ")}</span><span className="truncate text-sm font-semibold">{complaint.reporter?.email || complaint.reporterId || "Customer"}</span></div><a href={complaint.targetUrl} target="_blank" rel="noreferrer" className="mt-1 block truncate font-mono text-xs text-primary hover:underline">{complaint.targetUrl}</a><p className="mt-2 text-sm leading-5 text-foreground/85">{complaint.reason}</p>{complaint.staffNote && <p className="mt-2 text-xs text-muted-foreground">Staff note: {complaint.staffNote}</p>}</div><div className="flex shrink-0 flex-wrap gap-2"><button type="button" onClick={() => onReview(complaint, "UNDER_REVIEW")} disabled={busyId === `complaint-${complaint.id}` || complaint.status === "UNDER_REVIEW"} className="rounded-md border border-primary/30 px-2.5 py-1.5 text-[11px] font-medium text-primary hover:bg-primary/10 disabled:opacity-40">Mark reviewing</button><button type="button" onClick={() => onReview(complaint, "RESOLVED")} disabled={busyId === `complaint-${complaint.id}` || complaint.status === "RESOLVED"} className="rounded-md border border-success/30 px-2.5 py-1.5 text-[11px] font-medium text-success hover:bg-success/10 disabled:opacity-40">Resolve</button><button type="button" onClick={() => onReview(complaint, "DISMISSED")} disabled={busyId === `complaint-${complaint.id}` || complaint.status === "DISMISSED"} className="rounded-md border border-border px-2.5 py-1.5 text-[11px] font-medium text-muted-foreground hover:bg-accent disabled:opacity-40">Dismiss</button></div></div><div className="text-[11px] text-muted-foreground">Submitted {new Date(complaint.createdAt).toLocaleString()}{complaint.project?.name ? ` · project ${complaint.project.name}` : ""}</div></div>)}</div></section></div>;
}

function MetricCard({ label, value, tone }: { label: string; value: number; tone: "success" | "warning" | "danger" | "neutral" }) {
  const styles = { success: "text-success", warning: "text-warning", danger: "text-destructive", neutral: "text-foreground" } as const;
  return <div className="surface-card p-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</div><div className={`mt-2 font-display text-2xl font-semibold ${styles[tone]}`}>{value}</div></div>;
}

function LegacyAiModelsTab({ configs, busyId, onSave, onHealthCheck }: { configs: AdminAiProviderConfig[]; busyId: string | null; onSave: (data: Partial<AdminAiProviderConfig> & Pick<AdminAiProviderConfig, "provider" | "model" | "useCase" | "secretRef">) => void; onHealthCheck: (config: AdminAiProviderConfig) => void }) {
  const [useCase, setUseCase] = useState<AdminAiProviderConfig["useCase"]>("DISCOVERY");
  const active = configs.find((item) => item.useCase === useCase);
  const [provider, setProvider] = useState<AdminAiProviderConfig["provider"]>("groq");
  const [model, setModel] = useState("openai/gpt-oss-20b");
  const [secretRef, setSecretRef] = useState("GROQ_API_KEY");
  const [enabled, setEnabled] = useState(false);
  const [priority, setPriority] = useState(1);
  const [timeoutMs, setTimeoutMs] = useState(20000);
  const [maxOutputTokens, setMaxOutputTokens] = useState(2000);
  const [temperature, setTemperature] = useState(0);
  const [matrixUnitSurcharge, setMatrixUnitSurcharge] = useState(1);

  useEffect(() => {
    if (!active) return;
    setProvider(active.provider); setModel(active.model); setSecretRef(active.secretRef); setEnabled(active.enabled); setPriority(active.priority); setTimeoutMs(active.timeoutMs); setMaxOutputTokens(active.maxOutputTokens); setTemperature(active.temperature); setMatrixUnitSurcharge(active.matrixUnitSurcharge);
  }, [active?.id]);

  return <div className="mt-6 grid gap-5 xl:grid-cols-[1.05fr_0.95fr]"><section className="surface-card p-5"><div className="flex items-center gap-2"><BrainCircuit className="h-4 w-4 text-primary" /><h2 className="font-display text-base font-semibold">AI model configuration</h2></div><p className="mt-1 text-xs leading-5 text-muted-foreground">Choose the provider and model for each V2 use case. API keys stay in Render secrets; this form stores only the secret reference.</p><form className="mt-5 grid gap-3" onSubmit={(event) => { event.preventDefault(); onSave({ provider, model: model.trim(), useCase, secretRef: secretRef.trim(), enabled, priority, timeoutMs, maxOutputTokens, temperature, matrixUnitSurcharge }); }}><label className="grid gap-1 text-xs text-muted-foreground">Use case<select value={useCase} onChange={(event) => setUseCase(event.target.value as AdminAiProviderConfig["useCase"])} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground"><option>DISCOVERY</option><option>PLANNING</option><option>BROWSER_AGENT</option><option>VISION</option><option>RECOVERY</option></select></label><div className="grid gap-3 sm:grid-cols-2"><label className="grid gap-1 text-xs text-muted-foreground">Provider<select value={provider} onChange={(event) => setProvider(event.target.value as AdminAiProviderConfig["provider"])} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground"><option value="groq">Groq</option><option value="openai">OpenAI</option><option value="gemini">Gemini</option><option value="openai_compatible">OpenAI-compatible</option></select></label><label className="grid gap-1 text-xs text-muted-foreground">Model<input value={model} onChange={(event) => setModel(event.target.value)} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground" /></label></div><label className="grid gap-1 text-xs text-muted-foreground">Deployment secret reference<input value={secretRef} onChange={(event) => setSecretRef(event.target.value)} placeholder="GROQ_API_KEY" className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground" /><span className="text-[11px]">Never paste the actual API key here.</span></label><div className="grid gap-3 sm:grid-cols-3"><label className="grid gap-1 text-xs text-muted-foreground">Priority<input type="number" min={1} max={100} value={priority} onChange={(event) => setPriority(Number(event.target.value))} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground" /></label><label className="grid gap-1 text-xs text-muted-foreground">Timeout ms<input type="number" min={1000} max={120000} value={timeoutMs} onChange={(event) => setTimeoutMs(Number(event.target.value))} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground" /></label><label className="grid gap-1 text-xs text-muted-foreground">Max output tokens<input type="number" min={16} max={8192} value={maxOutputTokens} onChange={(event) => setMaxOutputTokens(Number(event.target.value))} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground" /></label></div><div className="grid gap-3 sm:grid-cols-2"><label className="grid gap-1 text-xs text-muted-foreground">Temperature<input type="number" min={0} max={1} step={0.05} value={temperature} onChange={(event) => setTemperature(Number(event.target.value))} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground" /></label><label className="grid gap-1 text-xs text-muted-foreground">Matrix surcharge units<input type="number" min={0} max={100} value={matrixUnitSurcharge} onChange={(event) => setMatrixUnitSurcharge(Number(event.target.value))} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm text-foreground" /></label></div><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} /> Activate this configuration for new work</label><button disabled={busyId === `ai-provider-${useCase}`} className="inline-flex items-center justify-center gap-1.5 rounded-md bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground disabled:opacity-50"><Check className="h-3.5 w-3.5" /> Save versioned configuration</button></form></section><section className="surface-card p-5"><div className="flex items-center gap-2"><Activity className="h-4 w-4 text-primary" /><h2 className="font-display text-base font-semibold">Configured providers</h2></div><p className="mt-1 text-xs leading-5 text-muted-foreground">Changing a configuration affects new scans/plans. Existing runs keep their configuration snapshot.</p><div className="mt-4 space-y-2">{configs.length === 0 ? <p className="text-sm text-muted-foreground">No database-managed provider configurations yet. The deployment environment fallback remains active.</p> : configs.map((config) => <div key={config.id} className="rounded-md border border-border/60 p-3"><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-medium">{config.provider} / {config.model}</div><div className="text-[11px] text-muted-foreground">{config.useCase} · v{config.configVersion} · {config.enabled ? "Active" : "Disabled"}</div></div><button type="button" onClick={() => onHealthCheck(config)} disabled={busyId === `ai-health-${config.id}`} className="rounded-md border border-border px-2 py-1 text-[11px] hover:bg-accent disabled:opacity-50">Health check</button></div><div className="mt-2 text-[11px] text-muted-foreground">Secret ref: {config.secretRef} · Status: {config.lastHealthStatus || "Not checked"}{config.lastHealthError ? ` · ${config.lastHealthError}` : ""}</div></div>)}</div></section></div>;
}

function ControlTowerTab({ snapshot, metrics, providers, onOpenAiModels }: { snapshot: AdminControlTowerSnapshot | null; metrics: AdminOperationsMetrics | null; providers: AdminAiProviderConfig[]; onOpenAiModels: () => void }) {
  if (!snapshot) return <div className="mt-6 surface-card p-8 text-sm text-muted-foreground">The control-tower snapshot is unavailable. Refresh to try again.</div>;
  const statusCount = (status: string) => snapshot.runs.statusCounts[status] ?? 0;
  const newestUsers = snapshot.users.recent.slice(0, 8);
  const newestRuns = snapshot.runs.recent.slice(0, 8);
  const providerRows = [...providers].sort((left, right) => left.useCase.localeCompare(right.useCase) || left.priority - right.priority);
  return <div className="mt-6 space-y-5">
    {metrics && <OperationsMetricsPanel metrics={metrics} />}
    <section className="surface-card overflow-hidden border-primary/25 bg-primary/[0.04] p-5 md:p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="flex items-center gap-2 text-[11px] font-mono uppercase tracking-[0.2em] text-primary"><ShieldCheck className="h-4 w-4" /> Product mission</div><h2 className="mt-2 max-w-3xl font-display text-xl font-semibold leading-tight">{snapshot.product.mission}</h2><p className="mt-2 text-xs text-muted-foreground">Runtime: {snapshot.product.runtime} · Deterministic customer fallback: {snapshot.product.deterministicCustomerFallback ? "enabled" : "disabled"}</p></div><div className="rounded-md border border-primary/20 bg-background/70 px-3 py-2 text-right text-[11px] text-muted-foreground"><div className="font-medium text-foreground">Control tower snapshot</div><div className="mt-1">{new Date(snapshot.generatedAt).toLocaleString()}</div></div></div></section>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric icon={Users} label="Users" value={String(snapshot.users.total)} detail={`+${snapshot.users.new24h} in 24h · +${snapshot.users.new30d} in 30d`} /><Metric icon={Database} label="Organizations" value={String(snapshot.organizations.total)} detail={`+${snapshot.organizations.new30d} in 30d`} /><Metric icon={Activity} label="Running" value={String(snapshot.queue.running)} detail={`${snapshot.queue.pending} pending`} /><Metric icon={ListChecks} label="Completed" value={String(snapshot.queue.completed)} detail={`${statusCount("FAILED")} failed · ${snapshot.queue.blocked} blocked`} /><Metric icon={BrainCircuit} label="Providers" value={String(snapshot.aiProviders.length)} detail={`${snapshot.aiProviders.filter((item) => item.enabled).length} active`} /><Metric icon={Mail} label="Unread alerts" value={String(snapshot.security.unreadNotifications)} detail="In-app notifications" /></div>
        <section className="surface-card overflow-hidden"><header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4"><div><h2 className="font-display text-base font-semibold">AI provider fleet</h2><p className="mt-1 text-xs text-muted-foreground">Primary and fallback capacity at a glance. Pool size shows references only; secret values never enter the browser.</p></div><button type="button" onClick={onOpenAiModels} className="text-xs font-medium text-primary hover:underline">Manage AI models</button>
</header><div className="grid gap-3 p-5 sm:grid-cols-2 xl:grid-cols-3">{providerRows.length ? providerRows.map((provider) => <article key={provider.id} className="rounded-md border border-border/70 bg-surface-2/20 p-3"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{provider.useCase} · {provider.priority === 1 ? "Primary" : `Fallback ${provider.priority - 1}`}</div><div className="mt-1 truncate text-sm font-semibold">{provider.provider}</div><div className="mt-1 truncate font-mono text-[11px] text-muted-foreground">{provider.model}</div></div><span className={`mt-1 h-2.5 w-2.5 rounded-full ${provider.runtimeStatus === "READY" && provider.lastHealthStatus !== "UNHEALTHY" ? "bg-success" : provider.runtimeStatus === "MISSING_SECRET" ? "bg-destructive" : "bg-warning"}`} title={provider.lastHealthStatus || provider.runtimeStatus || "Not checked"} /> </div><div className="mt-3 flex flex-wrap gap-x-3 gap-y-1 text-[11px] text-muted-foreground"><span>{provider.enabled ? "Eligible" : "Disabled"}</span><span>{provider.secretSource === "POOL" ? `Pool · ${provider.configuredPoolKeys ?? 0} keys` : provider.secretSource === "MANAGED" ? "Managed vault" : provider.secretSource === "DEPLOYMENT" ? "Deployment secret" : "Missing secret"}</span></div><div className="mt-2 text-[11px] text-muted-foreground">Health: {provider.lastHealthStatus || "Not checked"}{provider.lastHealthCheckedAt ? ` · ${new Date(provider.lastHealthCheckedAt).toLocaleString()}` : ""}</div></article>) : <p className="text-sm text-muted-foreground">No database-managed AI providers configured. The fallback environment path is visible in Telemetry.</p>}</div></section>
    <div className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]"><section className="surface-card overflow-hidden"><header className="border-b border-border px-5 py-4"><h2 className="font-display text-base font-semibold">Recent runs</h2>
<p className="mt-1 text-xs text-muted-foreground">Operational view of the latest AI browser work. Open the run to inspect the Wow Report and evidence.</p></header><div className="divide-y divide-border">{newestRuns.length ? newestRuns.map((run) => <div key={run.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-3 text-xs"><div className="min-w-0"><div className="truncate font-medium">{run.targetUrl}</div><div className="mt-1 text-muted-foreground">{run.type} · {new Date(run.createdAt).toLocaleString()}</div></div><div className="text-right"><div className="font-mono uppercase tracking-wider text-foreground">{run.status}</div>{run.errorMessage && <div className="mt-1 max-w-xs truncate text-destructive">{run.errorMessage}</div>}</div></div>) : <p className="px-5 py-8 text-sm text-muted-foreground">No runs recorded yet.</p>}</div></section><section className="surface-card overflow-hidden"><header className="border-b border-border px-5 py-4"><h2 className="font-display text-base font-semibold">Queue and capacity</h2><p className="mt-1 text-xs text-muted-foreground">The queue protects the provider while preserving customer-credit trust.</p></header><div className="grid grid-cols-2 gap-3 p-5">{[["Pending", snapshot.queue.pending], ["Running", snapshot.queue.running], ["Blocked", snapshot.queue.blocked], ["Failed", snapshot.queue.failed], ["Completed", snapshot.queue.completed]].map(([label, value]) => <div key={String(label)} className="rounded-md border border-border/60 p-3"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 font-display text-xl font-semibold">{String(value)}</div></div>)}</div><div className="border-t border-border px-5 py-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">Provider reservations</div><div className="mt-3 space-y-2">{Object.entries(snapshot.queue.capacityByStatus).length ? Object.entries(snapshot.queue.capacityByStatus).map(([status, value]) => <div key={status} className="flex items-center justify-between text-xs"><span className="uppercase tracking-wider">{status}</span><span className="text-muted-foreground">{value.reservations} reservations · {value.estimatedUnits} estimated units</span></div>) : <span className="text-xs text-muted-foreground">No active provider reservations.</span>}</div></div></section></div>
    <div className="grid gap-5 xl:grid-cols-2"><section className="surface-card overflow-hidden"><header className="border-b border-border px-5 py-4"><h2 className="font-display text-base font-semibold">New users and leads</h2><p className="mt-1 text-xs text-muted-foreground">Accounts are visible for operations; marketing-lead tracking remains intentionally separate and disabled.</p></header><div className="divide-y divide-border">{newestUsers.map((person) => <div key={person.id} className="flex items-center justify-between gap-3 px-5 py-3 text-xs"><div><div className="font-medium">{person.fullName || person.email}</div><div className="mt-1 text-muted-foreground">{person.email} · {new Date(person.createdAt).toLocaleString()}</div></div><div className="text-right text-muted-foreground">{person.isStaff ? "Staff" : person.emailVerified ? "Verified" : "Unverified"}</div></div>)}{newestUsers.length === 0 && <p className="px-5 py-8 text-sm text-muted-foreground">No users recorded yet.</p>}</div><div className="border-t border-border px-5 py-3 text-xs text-muted-foreground">Lead tracking: {snapshot.users.leadTracking.tracked ? "enabled" : "not enabled"}. {snapshot.users.leadTracking.reason}</div></section><section className="surface-card overflow-hidden"><header className="border-b border-border px-5 py-4"><h2 className="font-display text-base font-semibold">Security and controls</h2><p className="mt-1 text-xs text-muted-foreground">The console shows what is tracked and what is intentionally not collected.</p></header><div className="grid gap-3 p-5 sm:grid-cols-2">{[["Customer suspension", snapshot.controls.customerAccountSuspension], ["Session revocation", snapshot.controls.customerSessionRevocation], ["Provider configuration", snapshot.controls.providerConfiguration], ["Allocation review", snapshot.controls.allocationReview], ["Login telemetry", snapshot.security.loginTelemetry.tracked], ["Country telemetry", snapshot.security.countryTelemetry.tracked]].map(([label, enabled]) => <div key={String(label)} className="flex items-center justify-between gap-3 rounded-md border border-border/60 px-3 py-2 text-xs"><span>{label}</span><span className={enabled ? "text-success" : "text-muted-foreground"}>{enabled ? "Enabled" : "Not collected"}</span></div>)}</div><div className="border-t border-border px-5 py-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">Recent staff audit events</div><div className="mt-3 space-y-2">{snapshot.security.recentStaffAuditEvents.slice(0, 5).map((event) => <div key={event.id} className="flex justify-between gap-3 text-xs"><span className="font-medium">{event.eventType}</span><span className="text-muted-foreground">{new Date(event.createdAt).toLocaleString()}</span></div>)}{snapshot.security.recentStaffAuditEvents.length === 0 && <span className="text-xs text-muted-foreground">No staff audit events yet.</span>}</div></div></section></div>
  </div>;
}

function OperationsMetricsPanel({ metrics }: { metrics: AdminOperationsMetrics }) {
  const current = metrics.current;
  const trend = metrics.trend;
  const maxRuns = Math.max(1, ...trend.map((bucket) => bucket.totalRuns));
  const percent = (value: number) => `${(value * 100).toFixed(1)}%`;
  const signed = (value: number, digits = 2) => `${value > 0 ? "+" : ""}${value.toFixed(digits)}`;
  const reportTime = formatDuration(current.averageTimeToFirstReportSec);
  return <section className="surface-card overflow-hidden border-primary/20"><header className="flex flex-wrap items-start justify-between gap-3 border-b border-border px-5 py-4"><div><div className="flex items-center gap-2 text-[10px] font-mono uppercase tracking-wider text-primary"><Activity className="h-3.5 w-3.5" /> Real operations metrics</div><h2 className="mt-1 font-display text-base font-semibold">What the platform did in the last {metrics.window.days} days</h2><p className="mt-1 text-xs text-muted-foreground">Values are calculated from persisted runs, evidence outcomes, queue state, and AI usage events. No sample deltas are used.</p></div><div className="text-right text-[11px] text-muted-foreground">Compared with the preceding {metrics.window.days} days</div></header><div className="grid gap-3 p-5 sm:grid-cols-2 xl:grid-cols-6"><Metric icon={CircleAlert} label="Findings captured" value={String(current.findingRuns)} detail={`${percent(current.findingRate)} of covered runs · ${signed(metrics.comparisons.findingRate.delta * 100, 1)} pp`} /><Metric icon={Check} label="Pass rate" value={percent(current.passRate)} detail={`${current.successfulRuns} successful terminal runs · ${signed(metrics.comparisons.totalRuns.delta, 0)} run delta`} /><Metric icon={Activity} label="Time to report" value={reportTime} detail={`${signed(metrics.comparisons.averageTimeToFirstReportSec.delta, 1)} sec vs prior`} /><Metric icon={Radio} label="Queue depth" value={String(current.queueDepth)} detail={`${signed(metrics.comparisons.queueDepth.delta, 0)} vs prior window`} /><Metric icon={CircleDollarSign} label="AI cost / run" value={formatUsd(current.ai.costPerRunUsd)} detail={`${current.ai.calls} calls · ${percent(current.ai.fallbackRate)} fallback`} /><Metric icon={RefreshCw} label="Repeat-run rate" value={percent(current.repeatRunRate)} detail={`${signed(metrics.comparisons.repeatRunRate.delta * 100, 1)} pp vs prior`} /></div><div className="grid gap-5 border-t border-border p-5 xl:grid-cols-[1.4fr_0.6fr]"><div><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-display text-sm font-semibold">Overall run trend</h3><p className="mt-1 text-xs text-muted-foreground">Passed, findings, failed, blocked, and running work per bucket.</p></div><div className="flex flex-wrap gap-3 text-[10px] text-muted-foreground"><span><i className="mr-1 inline-block h-2 w-2 bg-success" />Passed</span><span><i className="mr-1 inline-block h-2 w-2 bg-primary" />Findings</span><span><i className="mr-1 inline-block h-2 w-2 bg-destructive" />Failed</span><span><i className="mr-1 inline-block h-2 w-2 bg-warning" />Blocked</span><span><i className="mr-1 inline-block h-2 w-2 bg-muted-foreground" />Running</span></div></div>{trend.length ? <div className="mt-4 grid min-h-[190px] grid-cols-7 items-end gap-2 border-b border-border pb-2">{trend.slice(-7).map((bucket) => <div key={bucket.bucketStart} className="flex min-w-0 flex-col items-center justify-end gap-2"><div className="flex h-36 items-end justify-center gap-0.5" title={`${bucket.label}: ${bucket.totalRuns} runs, queue depth ${bucket.queueDepth}`}><span className="w-2 bg-success" style={{ height: `${Math.max(3, ((bucket.completed / maxRuns) * 120))}px` }} /><span className="w-2 bg-primary" style={{ height: `${Math.max(3, ((bucket.passedWithFindings / maxRuns) * 120))}px` }} /><span className="w-2 bg-destructive" style={{ height: `${Math.max(3, ((bucket.failed / maxRuns) * 120))}px` }} /><span className="w-2 bg-warning" style={{ height: `${Math.max(3, ((bucket.blocked / maxRuns) * 120))}px` }} /><span className="w-2 bg-muted-foreground" style={{ height: `${Math.max(3, ((bucket.running / maxRuns) * 120))}px` }} /></div><span className="max-w-full truncate text-[10px] text-muted-foreground">{bucket.label.slice(5)}</span></div>)}</div> : <p className="mt-8 text-sm text-muted-foreground">No run activity was recorded in this period.</p>}</div><div><h3 className="font-display text-sm font-semibold">Period comparison</h3><dl className="mt-3 divide-y divide-border border-y border-border text-xs"><ComparisonRow label="Runs" item={metrics.comparisons.totalRuns} /><ComparisonRow label="Finding rate" item={metrics.comparisons.findingRate} percentValue /><ComparisonRow label="Queue depth" item={metrics.comparisons.queueDepth} /><ComparisonRow label="Provider waits" item={metrics.comparisons.providerExhaustionFrequency} /><ComparisonRow label="AI cost / run" item={metrics.comparisons.aiCostPerRunUsd} currency /></dl><p className="mt-3 text-[11px] leading-5 text-muted-foreground">Provider wait counts include queued runs and reservations classified as capacity-waiting. AI costs are internal estimates.</p></div></div></section>;
}

function ComparisonRow({ label, item, percentValue, currency }: { label: string; item: { current: number; previous: number; delta: number }; percentValue?: boolean; currency?: boolean }) {
  const display = (value: number) => currency ? formatUsd(value) : percentValue ? `${(value * 100).toFixed(1)}%` : String(Math.round(value * 100) / 100);
  return <div className="flex items-center justify-between gap-3 py-2.5"><dt className="text-muted-foreground">{label}</dt><dd className="text-right"><span className="font-medium text-foreground">{display(item.current)}</span><span className="ml-2 text-[10px] text-muted-foreground">prev {display(item.previous)}</span></dd></div>;
}

function formatDuration(seconds: number) {
  if (!Number.isFinite(seconds) || seconds <= 0) return "—";
  if (seconds < 60) return `${Math.round(seconds)}s`;
  return `${Math.floor(seconds / 60)}m ${Math.round(seconds % 60)}s`;
}

function QueueTab({ requests, busyId, onReview }: { requests: AdminAllocationRequest[]; busyId: string | null; onReview: (request: AdminAllocationRequest, status: "APPROVED" | "DECLINED") => void }) { return <section className="mt-6 space-y-3">{requests.length === 0 ? <div className="surface-card p-8 text-sm text-muted-foreground">No pending allocation requests. New requests will appear here with the requester, organization, workspace, and requested Matrix Units.</div> : requests.map((request) => <article key={request.id} className="surface-card p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h2 className="font-display text-base font-semibold">{request.requestedUnits} ⟐ requested</h2><span className="rounded-full bg-warning/15 px-2 py-0.5 text-[10px] uppercase tracking-wider text-warning">{request.status}</span></div><p className="mt-1 text-xs text-muted-foreground">{request.organization.name} · {request.workspace.name} · {request.requestedBy.fullName || request.requestedBy.email}</p></div><div className="flex gap-2"><button disabled={busyId === request.id} type="button" onClick={() => onReview(request, "DECLINED")} className="inline-flex items-center gap-1.5 rounded-md border border-border px-3 py-2 text-xs font-medium text-destructive hover:bg-destructive/10 disabled:opacity-50"><X className="h-3.5 w-3.5" /> Decline</button><button disabled={busyId === request.id} type="button" onClick={() => onReview(request, "APPROVED")} className="inline-flex items-center gap-1.5 rounded-md bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground disabled:opacity-50"><Check className="h-3.5 w-3.5" /> Approve</button></div></div><p className="mt-4 border-l-2 border-primary/40 pl-3 text-sm leading-6 text-muted-foreground">{request.reason}</p><p className="mt-3 text-[11px] text-muted-foreground">Submitted {new Date(request.createdAt).toLocaleString()}</p></article>)}</section>; }

function NotificationsTab(props: { recipients: StaffNotificationRecipient[]; recipientEmail: string; recipientLabel: string; setRecipientEmail: (value: string) => void; setRecipientLabel: (value: string) => void; busyId: string | null; onSave: (event: React.FormEvent) => void; onDisable: (recipient: StaffNotificationRecipient) => void; broadcastTitle: string; broadcastMessage: string; broadcastAudience: "ALL_USERS" | "STAFF"; setBroadcastTitle: (value: string) => void; setBroadcastMessage: (value: string) => void; setBroadcastAudience: (value: "ALL_USERS" | "STAFF") => void; onBroadcast: (event: React.FormEvent) => void }) { return <div className="mt-6 grid gap-5 xl:grid-cols-2"><section className="surface-card p-5"><div className="flex items-center gap-2"><Mail className="h-4 w-4 text-primary" /><h2 className="font-display text-base font-semibold">Staff email recipients</h2></div><p className="mt-1 text-xs leading-5 text-muted-foreground">Allocation requests are also sent to every enabled address below through Resend.</p><form onSubmit={props.onSave} className="mt-4 grid gap-2 sm:grid-cols-[1fr_1fr_auto]"><input type="email" required value={props.recipientEmail} onChange={(event) => props.setRecipientEmail(event.target.value)} placeholder="staff@matrixqa.com" className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm" /><input value={props.recipientLabel} onChange={(event) => props.setRecipientLabel(event.target.value)} placeholder="Label (optional)" className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm" /><button disabled={props.busyId === "recipient"} className="inline-flex items-center justify-center gap-1.5 rounded-md bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground disabled:opacity-50"><Send className="h-3.5 w-3.5" /> Save</button></form><div className="mt-4 space-y-2">{props.recipients.map((recipient) => <div key={recipient.id} className="flex items-center justify-between gap-3 rounded-md border border-border/60 px-3 py-2"><div><div className="text-sm">{recipient.email}</div><div className="text-[11px] text-muted-foreground">{recipient.label || "Staff recipient"} · {recipient.enabled ? "Enabled" : "Disabled"}</div></div>{recipient.enabled && <button type="button" onClick={() => props.onDisable(recipient)} disabled={props.busyId === recipient.id} className="text-xs text-destructive hover:underline">Disable</button>}</div>)}</div></section><section className="surface-card p-5"><div className="flex items-center gap-2"><Radio className="h-4 w-4 text-primary" /><h2 className="font-display text-base font-semibold">In-app broadcast</h2></div><p className="mt-1 text-xs leading-5 text-muted-foreground">Send an operational message to all customer accounts or Matrix QA staff.</p><form onSubmit={props.onBroadcast} className="mt-4 space-y-3"><input required minLength={3} maxLength={120} value={props.broadcastTitle} onChange={(event) => props.setBroadcastTitle(event.target.value)} placeholder="Notification title" className="w-full rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm" /><textarea required minLength={3} maxLength={2000} value={props.broadcastMessage} onChange={(event) => props.setBroadcastMessage(event.target.value)} placeholder="Message" className="min-h-28 w-full rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm" /><div className="flex flex-wrap items-center justify-between gap-3"><select value={props.broadcastAudience} onChange={(event) => props.setBroadcastAudience(event.target.value as "ALL_USERS" | "STAFF")} className="rounded-md border border-border bg-surface-2/40 px-3 py-2 text-sm"><option value="ALL_USERS">All users</option><option value="STAFF">Staff only</option></select><button disabled={props.busyId === "broadcast"} className="inline-flex items-center gap-1.5 rounded-md bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground disabled:opacity-50"><Send className="h-3.5 w-3.5" /> Send broadcast</button></div></form></section></div>; }

function TelemetryTab({ telemetry, health }: { telemetry: AdminTelemetrySummary | null; health: WorkerHealth | null }) {
  const sum = telemetry?.sums || {};
  const ai = telemetry?.aiUsage;
  const aiTotals = ai?.totals;
  const creditUsage = telemetry?.creditUsage;
  const capacity = telemetry?.providerCapacity;
  const capacityWindow = capacity?.window;
  const capacityBudget = capacity?.configuration.dailyBudget ?? 0;
  return <div className="mt-6 space-y-5">
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={Activity} label="Runs measured" value={String(telemetry?.totals ?? 0)} detail={`Build ${telemetry?.version.build ?? "1.6.2"}`} /><Metric icon={Database} label="Worker time" value={`${Math.round(Number(sum.workerTimeMs || 0) / 3600000 * 10) / 10} h`} detail="Recorded terminal runs" /><Metric icon={Database} label="Artifact bytes" value={formatBytes(Number(sum.artifactBytes || 0))} detail="Evidence and video uploads" /><Metric icon={Radio} label="R2 operations" value={String(sum.r2OperationCount || 0)} detail="Put/get/delete counts" /></div>
    <div className={`surface-card flex items-start gap-3 p-5 ${health?.healthy ? "" : "border-destructive/40"}`}><div className={`mt-0.5 flex h-8 w-8 items-center justify-center rounded-full ${health?.healthy ? "bg-success/15 text-success" : "bg-destructive/15 text-destructive"}`}><Activity className="h-4 w-4" /></div><div><h2 className="font-display text-base font-semibold">Worker health {health?.healthy ? "looks healthy" : "needs attention"}</h2><p className="mt-1 text-xs text-muted-foreground">{health?.activeRuns ?? 0} active runs · {health?.staleRuns ?? 0} stale heartbeats · last checked {health?.checkedAt ? new Date(health.checkedAt).toLocaleString() : "—"}</p></div>{!health?.healthy && <CircleAlert className="ml-auto h-5 w-5 text-destructive" />}</div>
    <section className="surface-card overflow-hidden"><header className="border-b border-border px-5 py-4"><h2 className="flex items-center gap-2 font-display text-base font-semibold"><BrainCircuit className="h-4 w-4 text-primary" />AI usage and cost</h2><p className="mt-1 text-xs text-muted-foreground">Estimated provider spend from sanitized AI calls. USD is an internal cost estimate; Matrix Units are the customer-facing usage surcharge and are tracked separately.</p></header><div className="grid gap-4 p-5 sm:grid-cols-2 xl:grid-cols-5"><Metric icon={BrainCircuit} label="AI calls" value={String(aiTotals?.events ?? 0)} detail={`${aiTotals?.degradedEvents ?? 0} degraded`} /><Metric icon={Database} label="AI tokens" value={String(aiTotals?.totalTokens ?? 0)} detail={`${aiTotals?.averageLatencyMs ?? 0} ms average`} /><Metric icon={CircleDollarSign} label="Estimated USD" value={formatUsd(aiTotals?.estimatedCostUsd ?? 0)} detail="Provider model estimate" /><Metric icon={CircleDollarSign} label="AI Matrix Units" value={`${aiTotals?.billableMatrixUnits ?? 0} ⟐`} detail="Successful enrichment surcharge" /><Metric icon={Activity} label="AI success" value={aiTotals?.events ? `${Math.round(((aiTotals.events - aiTotals.degradedEvents) / aiTotals.events) * 100)}%` : "—"} detail="Non-degraded calls" /></div>{ai && <div className="grid gap-5 border-t border-border p-5 xl:grid-cols-2"><div><h3 className="font-display text-sm font-semibold">Provider/model breakdown</h3><div className="mt-3 divide-y divide-border border-y border-border">{ai.providers.length ? ai.providers.map((provider) => <div key={`${provider.provider}-${provider.model}`} className="flex flex-wrap items-center justify-between gap-3 py-3 text-xs"><div><div className="font-medium">{provider.provider} · {provider.model}</div><div className="text-muted-foreground">{provider.events} calls · {provider.totalTokens} tokens · {provider.degradedEvents} degraded</div></div><div className="text-right"><div className="font-mono">{formatUsd(provider.estimatedCostUsd)}</div><div className="text-muted-foreground">{provider.billableMatrixUnits} ⟐</div></div></div>) : <p className="py-4 text-xs text-muted-foreground">No AI calls recorded yet.</p>}</div></div><div><h3 className="font-display text-sm font-semibold">Use-case breakdown</h3><div className="mt-3 divide-y divide-border border-y border-border">{ai.useCases.length ? ai.useCases.map((item) => <div key={item.useCase} className="flex flex-wrap items-center justify-between gap-3 py-3 text-xs"><div><div className="font-medium">{item.useCase}</div><div className="text-muted-foreground">{item.events} calls · {item.totalTokens} tokens · {item.degradedEvents} degraded</div></div><div className="text-right"><div className="font-mono">{formatUsd(item.estimatedCostUsd)}</div><div className="text-muted-foreground">{item.billableMatrixUnits} ⟐</div></div></div>) : <p className="py-4 text-xs text-muted-foreground">No use-case AI usage recorded yet.</p>}</div></div><div><h3 className="font-display text-sm font-semibold">Organization breakdown</h3><div className="mt-3 divide-y divide-border border-y border-border">{ai.organizations.length ? ai.organizations.slice(0, 10).map((organization) => <div key={organization.organizationId} className="flex flex-wrap items-center justify-between gap-3 py-3 text-xs"><div><div className="font-medium">{organization.organizationName}</div><div className="text-muted-foreground">{organization.events} calls · {organization.totalTokens} tokens · {organization.degradedEvents} degraded</div></div><div className="text-right"><div className="font-mono">{formatUsd(organization.estimatedCostUsd)}</div><div className="text-muted-foreground">{organization.billableMatrixUnits} ⟐</div></div></div>) : <p className="py-4 text-xs text-muted-foreground">No organization AI usage recorded yet.</p>}</div></div></div>}</section>
    <section className="surface-card overflow-hidden"><header className="border-b border-border px-5 py-4"><h2 className="font-display text-base font-semibold">Credit and infrastructure reconciliation</h2><p className="mt-1 text-xs text-muted-foreground">This is the platform-wide ledger view; customer Matrix Units remain separate from internal provider invoices and infrastructure cost.</p></header><div className="grid gap-4 p-5 sm:grid-cols-2 xl:grid-cols-5"><Metric icon={CircleDollarSign} label="Reserved (outstanding)" value={`${creditUsage?.reservedUnits ?? 0} ⟐`} detail={`${creditUsage?.grossReservedUnits ?? creditUsage?.reservedUnits ?? 0} gross · ${creditUsage?.reservedInternalCredits ?? 0} internal`} /><Metric icon={Check} label="Settled" value={`${creditUsage?.settledUnits ?? 0} ⟐`} detail={`${creditUsage?.settledInternalCredits ?? 0} internal`} /><Metric icon={RefreshCw} label="Refunded" value={`${creditUsage?.refundedUnits ?? 0} ⟐`} detail={`${creditUsage?.refundedInternalCredits ?? 0} internal`} /><Metric icon={Activity} label="Video time" value={`${Math.round(Number(sum.videoTimeMs || 0) / 60000)} min`} detail="FFmpeg/video boundary" /><Metric icon={Mail} label="Email volume" value={String(sum.emailCount || 0)} detail="Per-run counter" /></div><div className="grid gap-4 border-t border-border p-5 sm:grid-cols-2"><Metric icon={Database} label="R2 puts" value={String(sum.r2PutCount || 0)} detail="Artifact uploads" /><Metric icon={Database} label="R2 gets" value={String(sum.r2GetCount || 0)} detail="Signed/read operations" /></div></section>
    {capacity && <section className="surface-card overflow-hidden"><header className="border-b border-border px-5 py-4"><h2 className="font-display text-base font-semibold">Provider capacity window</h2><p className="mt-1 text-xs text-muted-foreground">Internal staff telemetry for the configured free-first provider. Customers see only Matrix Units and queue/reset messaging.</p></header><div className="grid gap-4 p-5 sm:grid-cols-2 xl:grid-cols-5"><Metric icon={Activity} label="Provider" value={capacity.configuration.provider} detail="Current capacity source" /><Metric icon={Database} label="Daily budget" value={String(capacityBudget)} detail={`${capacity.configuration.organizationSlots} logical slots`} /><Metric icon={ShieldCheck} label="Protected reserve" value={String(capacity.configuration.protectedReserve)} detail={`${capacity.configuration.alphaOrganizations} alpha organizations`} /><Metric icon={Activity} label="Reserved" value={String(capacityWindow?.reservedUnits ?? 0)} detail={`${Math.round((capacityWindow?.reservedUnits ?? 0) / Math.max(1, capacityBudget) * 100)}% of budget`} /><Metric icon={Check} label="Consumed / released" value={`${capacityWindow?.consumedUnits ?? 0} / ${capacityWindow?.releasedUnits ?? 0}`} detail="Settled provider units" /></div><div className="border-t border-border p-5"><h3 className="font-display text-sm font-semibold">Reservation status</h3><div className="mt-3 grid gap-2 sm:grid-cols-3">{Object.entries(capacity.reservationsByStatus).map(([status, item]) => <div key={status} className="rounded-md border border-border/60 p-3 text-xs"><div className="font-medium uppercase tracking-wider">{status}</div><div className="mt-1 text-muted-foreground">{item.reservations} reservations · {item.estimatedUnits} estimated units · {item.actualUnits} actual units</div></div>)}{Object.keys(capacity.reservationsByStatus).length === 0 && <p className="text-xs text-muted-foreground">No provider reservations in the current UTC window.</p>}</div></div></section>}
  </div>;
}

function Metric({ icon: Icon, label, value, detail }: { icon: typeof Activity; label: string; value: string; detail: string }) { return <div className="surface-card p-4"><div className="flex items-center gap-2 text-[11px] uppercase tracking-wider text-muted-foreground"><Icon className="h-3.5 w-3.5" />{label}</div><div className="mt-2 font-display text-2xl font-semibold">{value}</div><div className="mt-1 text-xs text-muted-foreground">{detail}</div></div>; }
function formatBytes(bytes: number) { if (!bytes) return "0 B"; const units = ["B", "KB", "MB", "GB"]; const index = Math.min(units.length - 1, Math.floor(Math.log(bytes) / Math.log(1024))); return `${Math.round(bytes / Math.pow(1024, index) * 10) / 10} ${units[index]}`; }
function formatUsd(value: number) { return `$${Number(value || 0).toFixed(8)}`; }
